--liquibase formatted sql
--changeset qrun:content-001-baseline context:baseline
CREATE TABLE cms_site (id uuid PRIMARY KEY, name varchar(200) NOT NULL UNIQUE, domain varchar(255) UNIQUE, default_locale varchar(10) NOT NULL DEFAULT 'en', created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE cms_asset (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES cms_site(id), uploader_id uuid, file_name varchar(255) NOT NULL, object_key varchar(1024) NOT NULL UNIQUE, mime_type varchar(100) NOT NULL, file_size bigint NOT NULL CHECK(file_size >= 0), checksum_sha256 varchar(64), alt_text varchar(500), caption text, upload_status varchar(20) NOT NULL CHECK(upload_status IN ('pending','processing','completed','failed')), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
CREATE TABLE cms_author (id uuid PRIMARY KEY, user_profile_id bigint NOT NULL UNIQUE, display_name varchar(200) NOT NULL, bio text, avatar_asset_id uuid REFERENCES cms_asset(id), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL);
ALTER TABLE cms_asset ADD CONSTRAINT fk_cms_asset_uploader FOREIGN KEY (uploader_id) REFERENCES cms_author(id);
CREATE TABLE cms_page (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES cms_site(id), title varchar(300) NOT NULL, slug varchar(255) NOT NULL, content jsonb NOT NULL CHECK(jsonb_typeof(content)='array'), publication_state varchar(20) NOT NULL CHECK(publication_state IN ('draft','scheduled','published','archived')), scheduled_at timestamptz, published_at timestamptz, seo_title varchar(300), seo_description varchar(500), meta_keywords varchar(500), structured_data jsonb, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(site_id,slug), CHECK(publication_state <> 'scheduled' OR scheduled_at IS NOT NULL));
CREATE TABLE cms_blog_post (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES cms_site(id), author_id uuid NOT NULL REFERENCES cms_author(id), title varchar(300) NOT NULL, slug varchar(255) NOT NULL, excerpt text, content jsonb NOT NULL CHECK(jsonb_typeof(content)='array'), featured_image_asset_id uuid REFERENCES cms_asset(id), publication_state varchar(20) NOT NULL CHECK(publication_state IN ('draft','scheduled','published','archived')), scheduled_at timestamptz, published_at timestamptz, archived_at timestamptz, seo_title varchar(300), seo_description varchar(500), meta_keywords varchar(500), structured_data jsonb, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(site_id,slug), CHECK(publication_state <> 'scheduled' OR scheduled_at IS NOT NULL));
CREATE TABLE cms_tag (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES cms_site(id), name varchar(150) NOT NULL, slug varchar(150) NOT NULL, description text, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(site_id,name), UNIQUE(site_id,slug));
CREATE TABLE cms_category (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES cms_site(id), parent_category_id uuid REFERENCES cms_category(id), name varchar(150) NOT NULL, slug varchar(150) NOT NULL, description text, created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(site_id,slug), CHECK(parent_category_id IS NULL OR parent_category_id <> id));
CREATE TABLE cms_navigation (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES cms_site(id), name varchar(150) NOT NULL, items jsonb NOT NULL CHECK(jsonb_typeof(items)='array'), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(site_id,name));
CREATE TABLE cms_redirect (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES cms_site(id), source_url varchar(1024) NOT NULL, destination_url varchar(1024) NOT NULL, type varchar(3) NOT NULL CHECK(type IN ('301','302')), description varchar(500), created_at timestamptz NOT NULL, updated_at timestamptz NOT NULL, UNIQUE(site_id,source_url));
CREATE TABLE cms_content_revision (id uuid PRIMARY KEY, content_type varchar(20) NOT NULL CHECK(content_type IN ('page','blog_post')), content_id uuid NOT NULL, revision_number int NOT NULL CHECK(revision_number > 0), previous_revision_id uuid REFERENCES cms_content_revision(id), user_profile_id bigint NOT NULL, snapshot jsonb NOT NULL, change_description varchar(500), created_at timestamptz NOT NULL, UNIQUE(content_type,content_id,revision_number));
CREATE INDEX ix_cms_page_publication ON cms_page(site_id,publication_state,published_at);
CREATE INDEX ix_cms_blog_post_publication ON cms_blog_post(site_id,publication_state,published_at);
CREATE INDEX ix_cms_blog_post_author ON cms_blog_post(author_id);
CREATE INDEX ix_cms_category_parent ON cms_category(parent_category_id);
CREATE INDEX ix_cms_asset_status ON cms_asset(site_id,upload_status);
CREATE INDEX ix_cms_revision_content ON cms_content_revision(content_type,content_id,revision_number DESC);
--rollback DROP TABLE cms_content_revision, cms_redirect, cms_navigation, cms_category, cms_tag, cms_blog_post, cms_page, cms_author, cms_asset, cms_site CASCADE;
